/// <summary>
/// Extension of form InventItemIdLookupSimple
/// </summary>
[ExtensionOf(formStr(InventItemIdLookupSimple))]
final class AVAInventItemIdLookupSimpleFrm_Extension
{
}

Method.Source:
/// <summary>
/// filters not only ItemId column but also NameAlias, NDXModelNumber and ProductName
/// </summary>
public void avaAddRanges()
{
    Query                   queryIILSimple  = inventItemIdLookupSimpleView_ds.query();
    QueryBuildDataSource    avaIILS_ds      = queryIILSimple.dataSourceTable(tableNum(InventItemIdLookupSimpleView));

    str filterTableStr = tableStr(InventItemIdLookupSimpleView);
    str filterFieldStr = fieldStr(InventItemIdLookupSimpleView, ItemId);

    Args avaArgs = this.args();
    FormControl avaFormControl;
    FilterValue filterValue;
    Name        filterStr;

    if(avaArgs.callerFormControl())
    {
        avaFormControl = avaArgs.callerFormControl();
    }
    else
    {
        avaFormControl = avaArgs.caller();
    }

    if (avaFormControl is FormReferenceGroupControl)
    {
        FormReferenceGroupControl avaReferenceControl = avaFormControl as FormReferenceGroupControl;
        filterValue = avaReferenceControl.filterValue(AbsoluteFieldBinding::construct(filterFieldStr, filterTableStr));
        filterStr = filterValue.value();
    }
    else if(avaFormControl is FormStringControl)
    {
        FormStringControl formStringControl = avaFormControl as FormStringControl;
        // User input values should be taken literally to maintain compatibility with the SysTableLookup functionality.
        filterStr = SysQueryRangeUtil::literalFilterValue(formStringControl.text());
    }

    if (filterStr != '')
    {   
        QueryBuildRange     nameRange;
        nameRange = SysQuery::findOrCreateRange(avaIILS_ds,fieldNum(InventItemIdLookupSimpleView, ItemId));
        nameRange.value(strFmt('((((%1.%2) like \"%3*\") || ((%1.%4) like \"%3*\") || ((%1.%5) like \"%3*\") || ((%1.%6) like \"%3*\")))',
                                avaIILS_ds.name(),
                                fieldStr(InventItemIdLookupSimpleView, ItemId),
                                filterStr,
                                fieldStr(InventItemIdLookupSimpleView, NameAlias),                                                                        
                                fieldStr(InventItemIdLookupSimpleView, NDXModelNumber),
                                fieldStr(InventItemIdLookupSimpleView, ProductName)));
    }


}
